func (a *Adapter) handleListInstances(reqHeaders map[string]string, replyToTopic string, l *zap.Logger) {
	if replyToTopic == "" { l.Warn(...); return }
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	instances, err := a.thunderAPI.ListInstances(ctx)
	if err != nil { // no invalid-input branch exists — always infrastructure-shaped
		a.sendErrorResponse(reqHeaders, replyToTopic, "list_instances", "thunder_api_error", err.Error(), "error_recoverable", l)
		return
	}
	a.sendSuccessResponse(reqHeaders, replyToTopic, "list_instances", map[string]interface{}{"count": len(instances), "instances": instances}, l)
}
